function draw() {
  background(0);

  for (let tile of tiles) {
    let col = selectColor();

    if (tile.isSmall) {
      if (flashFlag) {
        let h = hue(col);
        let s = saturation(col);
        let b = brightness(col) + 30;
        col = color(h, s, constrain(b, 0, 100));
      }
    } else {
      col = getModifiedColor(col);
    }

    tint(col);
    stroke(col);
    strokeWeight(tile.w / borderThick);

    let drawEmoji = tile.isSmall && R.random_dec() < 0.2;
    let currentImage;

    if (!drawEmoji) {
      currentImage = R.random_dec() < 0.5 ? img : R.random_choice(distortedImages);
      if (R.random_dec() < 0.3 && scanlineDistortionFrameCount < scanMaxFrameCount) {
        currentImage = scanlineDistortion(currentImage);
        scanlineDistortionFrameCount++;
      } else {
        scanlineDistortionFrameCount = 0;
      }

      let srcW = currentImage.width * (1 - zoom);
      let srcH = currentImage.height * (1 - zoom);
      let srcX = (currentImage.width - srcW) * srcXRan;
      let srcY = (currentImage.height - srcH) * srcYRan;

      // Push and translate for rotation
      push();
      translate(tile.x + tile.w / 2, tile.y + tile.h / 2);
      rotate((PI / 2) * floor(R.random_num(1, 4)));
      image(
        currentImage,
        -tile.w / 2,
        -tile.h / 2,
        tile.w,
        tile.h,
        srcX,
        srcY,
        srcW,
        srcH
      );
      pop();
    }

    if (drawEmoji) {
      let chosenEmoji = R.random_choice([img2, img3, img4, img5, img6]);
      image(chosenEmoji, tile.x, tile.y, tile.w, tile.h);
    } else {
      noFill();
      rect(tile.x, tile.y, tile.w, tile.h);
    }
  }

  flashFlag = !flashFlag; 

  noTint();
  image(overlay, 0, 0);
  loadPixels();
  addGrainEffect();
  updatePixels();
  noLoop(); 
  applyOldPaperEffect();
}

function createMosaicPattern() {
  while (y < height) {
    let x = -offScreenAmount;

    while (x < width) {
      let decision = R.random_dec();
      let remainingHeight = height - y;

      if (
        y + squareSize <= height + squareSize &&
        remainingHeight !== squareSize
      ) {

        if (decision < 0.5 && x + squareSize * 2 <= width) {
          tiles.push({
            x: x,
            y: y,
            w: squareSize,
            h: squareSize,
            isSmall: false,
          });
          x += squareSize;

          let smallerPanelsCount = floor(R.random_num(2, 10));
          let smallerPanelSize = squareSize / smallerPanelsCount;

          if (y + smallerPanelSize * smallerPanelsCount <= height) {
            for (let i = 0; i < smallerPanelsCount && x < width; i++) {
              tiles.push({
                x: x,
                y: y + i * smallerPanelSize,
                w: smallerPanelSize,
                h: smallerPanelSize,
                isSmall: true,
              });
            }
            x += smallerPanelSize;
          } else {
            tiles.push({
              x: x,
              y: y,
              w: squareSize,
              h: squareSize,
              isSmall: false,
            });
            x += squareSize;
          }
        } else {
          tiles.push({
            x: x,
            y: y,
            w: squareSize,
            h: squareSize,
            isSmall: false,
          });
          x += squareSize;
        }
      } else {
        squareSize = remainingHeight;
        if (decision < 0.5 && x + squareSize * 2 <= width) {
          tiles.push({
            x: x,
            y: y,
            w: squareSize,
            h: squareSize,
            isSmall: false,
          });
          x += squareSize;

          let smallerPanelsCount = floor(R.random_num(2, 6));
          let smallerPanelSize = squareSize / smallerPanelsCount;

          for (let i = 0; i < smallerPanelsCount && x < width; i++) {
            tiles.push({
              x: x,
              y: y + i * smallerPanelSize,
              w: min(smallerPanelSize, width - x),
              h: smallerPanelSize,
              isSmall: true,
            });
          }
          x += smallerPanelSize;
        } else {
          tiles.push({
            x: x,
            y: y,
            w: min(squareSize, width - x),
            h: squareSize,
            isSmall: false,
          });
          x += squareSize;
        }
      }
    }
    y += squareSize;
  }
}

function createOverlay() {
  overlay = createGraphics(width, height); 
  overlay.noStroke(); 

  for (let y = 0; y < overlay.height; y++) {
    for (let x = 0; x < overlay.width; x++) {
      let shortestDistToEdge = min(x, y, overlay.width - x, overlay.height - y);

      let noiseValue = noise(x * noiseScale, y * noiseScale);
      shortestDistToEdge += map(noiseValue, 0, 1, -fadeStart, fadeStart);

      let alpha =
        map(shortestDistToEdge, 0, fadeStart, 255, 0) * (overlayAlpha / 255);
      alpha = constrain(alpha, 0, 255); 

      overlay.fill(255, 255, 255, alpha); 
      overlay.rect(x, y, 1, 1); 
    }
  }
}

function selectColor() {
  let r = R.random_num(0,100);

  if (r < 85) {
    return colors[0];
  } else if (r < 95) {
    return colors[1];
  } else {
    return colors[2];
  }
}

function shuffleArray(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = floor(R.random_dec() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]]; // Swap elements
  }
}

function getModifiedColor(baseColor) {
  let h = hue(baseColor);
  let s = saturation(baseColor);
  let b = brightness(baseColor);

  h = (h + R.random_num(-15, 15) + 360) % 360;

  s = constrain(s + R.random_num(-5, 20), 0, 100);
  b = constrain(b + R.random_num(-5, 20), 0, 100);

  return color(h, s, b);
}

function addGrainEffect() {
  for (let i = 0; i < pixels.length; i += 4) {
    let h = pixels[i] + R.random_num(-grainAmountHue, grainAmountHue);
    let s = pixels[i + 1];
    let b = pixels[i + 2]; 
    let a = pixels[i + 3];

    pixels[i] = h;
    pixels[i + 1] = s;
    pixels[i + 2] = b;
    pixels[i + 3] = a;
  }
}

function colorDistortion(inputImg) {
  let distortedImg = createImage(inputImg.width, inputImg.height);
  distortedImg.loadPixels();
  inputImg.loadPixels();
  for (let i = 0; i < inputImg.pixels.length; i += 4) {
    distortedImg.pixels[i] = 255 - inputImg.pixels[i]; 
    distortedImg.pixels[i + 2] = 255 - inputImg.pixels[i + 2]; 
    distortedImg.pixels[i + 1] = inputImg.pixels[i + 1]; 
    distortedImg.pixels[i + 3] = inputImg.pixels[i + 3];
  }
  distortedImg.updatePixels();
  return distortedImg;
}

function scanlineDistortion(inputImg) {
  let distortedImg = createImage(inputImg.width, inputImg.height);
  distortedImg.loadPixels();
  inputImg.loadPixels();

  let i = 0;
  while (i < inputImg.height) {
    let yOffset = floor(R.random_num(-20, 20)); 
    let distortHeight = floor(R.random_num(1, 20)); 
    for (let x = 0; x < inputImg.width; x++) {
      for (let j = 0; j < distortHeight && i + j < inputImg.height; j++) {
        let col = inputImg.get(
          x,
          constrain(i + j + yOffset, 0, inputImg.height - 1)
        );
        distortedImg.set(x, i + j, col);
      }
    }

    i += distortHeight;
  }

  distortedImg.updatePixels();
  return distortedImg;
}

function sizeShapeDistortion(inputImg, iterations) {
  let currentImg = inputImg;

  for (let i = 0; i < iterations; i++) {
    let distortedImg = createImage(currentImg.width, currentImg.height);
    distortedImg.loadPixels();
    currentImg.loadPixels();

    for (let y = 0; y < currentImg.height; y++) {
      for (let x = 0; x < currentImg.width; x++) {
        let offsetX = x + sin(y * 0.05) * offsetRanX;
        let offsetY = y + sin(x * 0.05) * offsetRanY;

        offsetX = constrain(floor(offsetX), 0, currentImg.width - 1);
        offsetY = constrain(floor(offsetY), 0, currentImg.height - 1);

        let col = currentImg.get(offsetX, offsetY);
        distortedImg.set(x, y, col);
      }
    }

    distortedImg.updatePixels();
    currentImg = distortedImg; 
  }

  return currentImg;
}

function scaleCanvas(p) {
  if (fixedSize == "On") {
    width = 2500;
    height = 2500;
  } else {
    width = p.windowWidth;
    height = p.windowHeight;
  }
  let aspectRatio = 1;
  let targetAspectRatio = aspectRatio;
  let windowAspectRatio = width / height;

  if (windowAspectRatio < targetAspectRatio) {
    height = width / targetAspectRatio;
  } else {
    width = height * targetAspectRatio;
  }
  p.resizeCanvas(width, height);
}

function applyOldPaperEffect() {
  loadPixels();

  for (let i = 0; i < pixels.length; i += 4) {
    let r = pixels[i];
    let g = pixels[i + 1];
    let b = pixels[i + 2];

    let noiseValue = noise(((i / 4) % width) * 0.1, floor(i / 4 / width) * 0.1);
    let paperColor = map(noiseValue, 0, 1, pColmin, pColmax);

    r = lerp(r, paperColor, 0.5);
    g = lerp(g, paperColor, 0.5);
    b = lerp(b, paperColor, 0.5);

    if (R.random_dec() < 0.00175) {
      r = paperColor - 20;
      g = paperColor - 10;
      b = 140;
    }

    pixels[i] = r;
    pixels[i + 1] = g;
    pixels[i + 2] = b;
  }

  updatePixels();
}
